def validate(form):
    errors = {}
    name = form.get('name', '').strip()
    if not name:
        errors['name'] = 'required'
    age = form.get('age', '')
    if not age.isdigit():
        errors['age'] = 'number'
    elif not 18 <= int(age) <= 60:
        errors['age'] = 'range'
    return errors

print(validate({'name': '  ', 'age': '-5'}), validate({'name': 'Ravi', 'age': '075'}))

