@app.route('/api/v1/courses', methods=['POST'])
def create_course():
    data = request.get_json(silent=True)          # None if body is not valid JSON
    if not isinstance(data, dict) or not data.get('code'):
        return {'error': 'code is required'}, 400
    if Course.query.filter_by(code=data['code']).first():
        return {'error': 'course already exists'}, 409
    c = Course(code=data['code'], title=data.get('title', ''))
    db.session.add(c)
    db.session.commit()
    body = {'id': c.id, 'code': c.code, 'title': c.title}
    return body, 201, {'Location': url_for('get_course', cid=c.id)}

